{
  "name": "Dubai Technology, Media and Free Zone Authority",
  "description": "Updated description"
}

{
  "code": "real_estate",
  "name": "Real Estate Contracts",
  "description": "Property purchase, sale, and rental agreements",
  "is_active": true
}

{
  "key": "dmcc_employment_rules_v1",
  "name": "DMCC Employment Rules v1.0",
  "description": "Standard employment rules for DMCC contracts",
  "authority_id": "{{authorityId}}",
  "clauses": [
    {
      "id": "clause_1",
      "title": "Probation Period",
      "content": "The employee shall be subject to a probation period of {probation_months} months.",
      "order": 1,
      "is_required": true
    },
    {
      "id": "clause_2",
      "title": "Working Hours",
      "content": "Standard working hours are 8 hours per day, 5 days per week as per UAE Labor Law.",
      "order": 2,
      "is_required": true
    },
    {
      "id": "clause_3",
      "title": "Notice Period",
      "content": "Either party may terminate this contract by providing 30 days written notice.",
      "order": 3,
      "is_required": true
    }
  ],
  "version": "1.0.0",
  "status": "active",
  "metadata": {
    "tags": ["employment", "dmcc", "standard"]
  }
}

{
  "name": "DMCC Employment Rules v1.1",
  "version": "1.1.0",
  "clauses": [
    {
      "id": "clause_1",
      "title": "Probation Period",
      "content": "The employee shall be subject to a probation period of {probation_months} months (maximum 6 months).",
      "order": 1,
      "is_required": true
    },
    {
      "id": "clause_2",
      "title": "Working Hours",
      "content": "Standard working hours are 8 hours per day, 5 days per week as per UAE Labor Law.",
      "order": 2,
      "is_required": true
    },
    {
      "id": "clause_3",
      "title": "Notice Period",
      "content": "Either party may terminate this contract by providing 30 days written notice.",
      "order": 3,
      "is_required": true
    },
    {
      "id": "clause_4",
      "title": "Annual Leave",
      "content": "Employee is entitled to 30 calendar days of annual leave per year.",
      "order": 4,
      "is_required": true
    }
  ]
}

{
  "name": "DMCC Employment Contract v1.1",
  "version": "1.1.0",
  "changelog": "Added benefits field and updated validation rules",
  "fields": [
    {
      "key": "employee_name",
      "label": "Employee Full Name",
      "type": "text",
      "required": true,
      "order": 1
    },
    {
      "key": "job_title",
      "label": "Job Title",
      "type": "text",
      "required": true,
      "order": 2
    },
    {
      "key": "salary",
      "label": "Monthly Salary (AED)",
      "type": "number",
      "required": true,
      "validation_rules": {
        "min": 3000,
        "max": 100000
      },
      "order": 3
    },
    {
      "key": "probation_months",
      "label": "Probation Period (Months)",
      "type": "number",
      "required": true,
      "default_value": 6,
      "validation_rules": {
        "min": 3,
        "max": 6
      },
      "order": 4
    },
    {
      "key": "start_date",
      "label": "Employment Start Date",
      "type": "date",
      "required": true,
      "order": 5
    },
    {
      "key": "benefits",
      "label": "Additional Benefits",
      "type": "textarea",
      "required": false,
      "placeholder": "List any additional benefits",
      "order": 6
    }
  ]
}
